import ee
ee.Initialize(project='earthsense-436113')

# 1. Geometry – Inner Niger Delta approximate bounds
delta = ee.Geometry.Polygon(
        [[[4.0, 16.0], [4.0, 14.0], [6.0, 14.0], [6.0, 16.0]]])

def veg_coverage(month_start, month_end, year, label, tries_s2=True):
    if tries_s2:
        col = (ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                 .filterBounds(delta)
                 .filterDate(f'{year}-{month_start}-01', f'{year}-{month_end}-30'))
        if col.size().getInfo() == 0:
            col = (ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                     .filterBounds(delta)
                     .filterDate(f'{year}-{month_start}-01', f'{year}-{month_end}-30'))
    else:
        col = (ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                 .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
                 .filterBounds(delta)
                 .filterDate(f'{year}-{month_start}-01', f'{year}-{month_end}-30'))
    if col.size().getInfo() == 0:
        return None, 0
    # Cloud mask & NDVI
    def maskS2(img):
        scl = img.select('SCL')
        mask = scl.eq(4).Or(scl.eq(5))
        return img.updateMask(mask).normalizedDifference(['B8','B4']).rename('NDVI')
    def maskL8(img):
        qa = img.select('QA_PIXEL')
        mask = qa.bitwiseAnd(1 << 3).eq(0).And(qa.bitwiseAnd(1 << 5).eq(0))
        return img.updateMask(mask).normalizedDifference(['SR_B5','SR_B4']).rename('NDVI')
    if 'COPERNICUS' in col.getInfo()['features'][0]['id']:
        col = col.map(maskS2)
    else:
        col = col.map(maskL8)
    mosaic = col.median()
    cov = mosaic.gt(0.4).rename('cov')
    total = cov.reduceRegion(reducer=ee.Reducer.count(), geometry=delta, scale=1000, maxPixels=1e9).get('cov')
    mean = cov.reduceRegion(reducer=ee.Reducer.mean(), geometry=delta, scale=1000, maxPixels=1e9).get('cov')
    return mean.getInfo(), total.getInfo()

nov, npx = veg_coverage(11,11,2022,'Nov')
may, mpx = veg_coverage(5,5,2022,'May')

if nov is None or may is None:
    print("C1")
elif npx == 0 or mpx == 0:
    print("C2")
elif nov is None or may is None:
    print("C3")
else:
    print(f"Nov22 cover: {nov:.3f}  May22: {may:.3f}  Pixels: {int(npx)}")
    print("<answer>A</answer>" if nov > may else "<answer>B</answer>")
